@layer components {
  .system-board {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
  }

  .system-board__title {
    font-size: var(--text-xs);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-muted-foreground);
  }

  .system-row {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    padding: var(--space-xs) var(--space-sm);
    border-radius: var(--radius-sm);
    background: var(--color-card);
    font-size: var(--text-sm);
    font-family: var(--font-mono);
  }

  .system-row[data-power="false"] {
    opacity: 0.5;
  }

  .system-row__label {
    flex: 1;
    font-weight: 500;
  }

  .system-row__power {
    font-size: var(--text-xs);
    font-weight: 600;
  }

  .system-row__status {
    width: 0.75rem;
    height: 0.75rem;
    border-radius: 50%;
    background: var(--color-muted);
  }

  .system-row[data-operational="green"] .system-row__status {
    background: var(--color-success, oklch(0.72 0.19 142));
  }

  .system-row[data-operational="yellow"] .system-row__status {
    background: var(--color-warning, oklch(0.80 0.18 84));
  }

  .system-row[data-operational="red"] .system-row__status {
    background: var(--color-destructive);
  }

  /* Stress bar */
  .stress-bar {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--text-sm);
    font-family: var(--font-mono);
  }

  .stress-bar__track {
    flex: 1;
    height: 0.5rem;
    border-radius: var(--radius-sm);
    background: var(--color-muted);
    overflow: hidden;
  }

  .stress-bar__fill {
    height: 100%;
    border-radius: var(--radius-sm);
    transition: width 0.3s ease;
  }

  .stress-bar[data-severity="low"] .stress-bar__fill {
    background: var(--color-success, oklch(0.72 0.19 142));
  }

  .stress-bar[data-severity="medium"] .stress-bar__fill {
    background: var(--color-warning, oklch(0.80 0.18 84));
  }

  .stress-bar[data-severity="high"] .stress-bar__fill {
    background: var(--color-destructive);
  }

  .stress-bar__label {
    min-width: 2ch;
    text-align: right;
    font-weight: 600;
  }
}

