            <span class="system-chip__label">{{ sys.label }}</span>
            <span class="system-chip__power">{{ sys.power ? "ON" : "OFF" }}</span>
          </span>
        }
      </div>
    }
  `,
})
export class SystemStatusBoardComponent {
  readonly systems = input<SystemSnapshot[]>([]);
}

