@layer components {
  .system-board {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-xs);
    padding: var(--space-xs) var(--space-lg, 1.5rem);
    border-bottom: 1px solid var(--color-border);
  }

  .system-board__title {
    font-size: var(--text-xs);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-muted-foreground);
    margin-right: var(--space-xs);
  }

  .system-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.15rem 0.5rem;
    border-radius: 2px;
    background: var(--color-card);
    font-size: var(--text-xs);
    font-family: var(--font-mono);
  }

  .system-chip[data-power="false"] {
    opacity: 0.5;
  }

  .system-chip__label {
    font-weight: 500;
  }

  .system-chip__traffic {
    display: inline-flex;
    gap: 3px;
    align-items: center;
  }

  .system-chip__light {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 50%;
    background: oklch(25% 0 0);
    flex-shrink: 0;
    transition: background 200ms ease, box-shadow 200ms ease;
  }

  /* Active lights */
  .system-chip[data-operational="green"] .system-chip__light[data-color="green"] {
    background: var(--color-success, oklch(0.72 0.19 142));
    box-shadow: 0 0 4px var(--color-success, oklch(0.72 0.19 142));
  }

  .system-chip[data-operational="yellow"] .system-chip__light[data-color="yellow"] {
    background: var(--color-warning, oklch(0.80 0.18 84));
    box-shadow: 0 0 4px var(--color-warning, oklch(0.80 0.18 84));
  }

  .system-chip[data-operational="red"] .system-chip__light[data-color="red"] {
    background: var(--color-destructive);
    box-shadow: 0 0 4px var(--color-destructive);
  }

  /* Powered off — all lights dim */
  .system-chip[data-power="false"] .system-chip__light {
    background: oklch(25% 0 0);
    box-shadow: none;
  }

  /* Stress bar */
  .stress-bar {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--text-sm);
    font-family: var(--font-mono);
  }

  .stress-bar__track {
    flex: 1;
    height: 0.5rem;
    border-radius: var(--radius-sm);
    background: var(--color-muted);
    overflow: hidden;
  }

  .stress-bar__fill {
    height: 100%;
    border-radius: var(--radius-sm);
    transition: width 0.3s ease;
  }

  .stress-bar[data-severity="low"] .stress-bar__fill {
    background: var(--color-success, oklch(0.72 0.19 142));
  }

  .stress-bar[data-severity="medium"] .stress-bar__fill {
    background: var(--color-warning, oklch(0.80 0.18 84));
  }

  .stress-bar[data-severity="high"] .stress-bar__fill {
    background: var(--color-destructive);
  }

  .stress-bar__label {
    min-width: 2ch;
    text-align: right;
    font-weight: 600;
  }
}

